def transform(grid):
    """Tile every foreground cell with 2x2 squares and L triominoes.

    A square is color 1. For an L triomino, the color identifies its
    missing corner: NW=4, NE=3, SW=2, SE=5.
    """
    h, w = len(grid), len(grid[0])
    cells = frozenset((r, c) for r in range(h) for c in range(w) if grid[r][c] != 0)
    pieces = []
    for r in range(h - 1):
        for c in range(w - 1):
            square = frozenset((rr, cc) for rr in (r, r + 1) for cc in (c, c + 1))
            if square <= cells:
                pieces.append((square, 1))
            for missing, color in (((r, c), 4), ((r, c + 1), 3),
                                   ((r + 1, c), 2), ((r + 1, c + 1), 5)):
                tri = frozenset((rr, cc) for rr in (r, r + 1) for cc in (c, c + 1)
                                if (rr, cc) != missing)
                if tri <= cells:
                    pieces.append((tri, color))

    @lru_cache(None)
    def tile(remaining):
        if not remaining:
            return ()
        remaining = frozenset(remaining)
        # Branch on the uncovered cell with the fewest currently viable pieces.
        viable = [(shape, color) for shape, color in pieces if shape <= remaining]
        if not viable:
            return None
        counts = {}
        for shape, _ in viable:
            for cell in shape:
                counts[cell] = counts.get(cell, 0) + 1
        pivot = min(remaining, key=lambda p: counts.get(p, 0))
        for shape, color in viable:
            if pivot in shape:
                rest = tile(frozenset(remaining - shape))
                if rest is not None:
                    return ((shape, color),) + rest
        return None

    solution = tile(tuple(sorted(cells)))
    if solution is None:
        raise ValueError('foreground cannot be tiled by the demonstrated pieces')
    out = [[0] * w for _ in range(h)]
    for shape, color in solution:
        for r, c in shape:
            out[r][c] = color
    return out


if __name__ == '__main__':
